package pe.animetv;
import android.os.Looper;import android.view.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import java.lang.reflect.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;
import static org.junit.Assert.*;import static pe.animetv.Models.*;

@RunWith(RobolectricTestRunner.class) @Config(sdk=28,qualifiers="w960dp-h540dp-land-xhdpi")
public class CatalogPaginationTest {
    public static class FakeActivity extends TvScreenTest.FakeActivity {
        static Map<Integer,List<Anime>> pages;static Set<Integer> failing;static List<String> calls;static CountDownLatch nextStarted,nextRelease;
        protected Source createSource(){return new Source(){
            public String id(){return "fake";}public String name(){return "Fake";}public String baseUrl(){return "https://example.test";}
            public List<Anime> catalog(String q,int page,Map<String,String> filters)throws Exception{calls.add(page+":"+q+":"+filters);if(page==2&&nextRelease!=null){nextStarted.countDown();nextRelease.await();}if(failing.contains(page))throw new java.io.IOException("page failed");return pages.getOrDefault(page,List.of());}
            public List<Models.Filter> filters(){return List.of();}public Detail detail(Anime a){return new Detail(a,"",List.of());}public List<Server> servers(Episode e){return List.of();}public Stream resolve(Server s,String e){return null;}public List<RecentEpisode> recent(){return List.of();}public List<CalendarEntry> calendar(){return List.of();}
        };}
    }
    private org.robolectric.android.controller.ActivityController<FakeActivity> controller;private MainActivity activity;
    private Anime item(String slug){return new Anime(slug,"https://example.test/anime/"+slug,"","Serie","Finalizado");}
    @Before public void setup(){FakeActivity.pages=new HashMap<>();FakeActivity.failing=new HashSet<>();FakeActivity.calls=Collections.synchronizedList(new ArrayList<>());FakeActivity.nextRelease=null;FakeActivity.nextStarted=null;controller=Robolectric.buildActivity(FakeActivity.class).setup().visible().windowFocusChanged(true);activity=controller.get();}
    @After public void stop(){if(FakeActivity.nextRelease!=null)FakeActivity.nextRelease.countDown();controller.pause().stop().destroy();}
    private Object field(String name)throws Exception{Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(activity);}
    private void set(String name,Object value)throws Exception{Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);f.set(activity,value);}
    private void load(int page)throws Exception{Method m=MainActivity.class.getDeclaredMethod("loadCatalog",int.class);m.setAccessible(true);m.invoke(activity,page);}
    @Test public void returningFromDetailResumesPendingNextWithoutReplacingCards()throws Exception{
        FakeActivity.pages.put(1,List.of(item("sao")));FakeActivity.pages.put(2,List.of(item("sao-ii")));FakeActivity.nextStarted=new CountDownLatch(1);FakeActivity.nextRelease=new CountDownLatch(1);load(1);assertTrue(FakeActivity.nextStarted.await(2,TimeUnit.SECONDS));Shadows.shadowOf(Looper.getMainLooper()).idle();Object original=field("catalogView");
        Method show=MainActivity.class.getDeclaredMethod("showDetail",Anime.class);show.setAccessible(true);show.invoke(activity,item("sao"));FakeActivity.nextRelease.countDown();FakeActivity.nextRelease=null;
        Method back=MainActivity.class.getDeclaredMethod("returnCatalog");back.setAccessible(true);back.invoke(activity);settle();assertSame(original,field("catalogView"));assertNotNull(find("catalog-next"));assertEquals(1,field("page"));
    }
    private void settle()throws Exception{for(int n=0;n<100;n++){Shadows.shadowOf(Looper.getMainLooper()).idle();View decor=activity.getWindow().getDecorView();decor.measure(View.MeasureSpec.makeMeasureSpec(1920,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1080,View.MeasureSpec.EXACTLY));decor.layout(0,0,1920,1080);Future<?> task=(Future<?>)field("foregroundTask");if(task!=null&&task.isDone()){for(int pass=0;pass<3;pass++){Shadows.shadowOf(Looper.getMainLooper()).idle();decor.measure(View.MeasureSpec.makeMeasureSpec(1920,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1080,View.MeasureSpec.EXACTLY));decor.layout(0,0,1920,1080);}return;}Thread.sleep(20);}fail("Catalogue did not finish");}
    private View find(String tag)throws Exception{return find((View)field("catalogView"),tag);}
    private View find(View root,String tag){if(tag.equals(root.getTag()))return root;if(root instanceof TvRowsView){for(View item:((TvRowsView)root).model.items){View result=find(item,tag);if(result!=null)return result;}}else if(root instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)root;for(int n=0;n<group.getChildCount();n++){View result=find(group.getChildAt(n),tag);if(result!=null)return result;}}return null;}
    @Test public void shortSwordArtSearchDoesNotShowNext()throws Exception{set("query","Sword Art Online");FakeActivity.pages.put(1,List.of(item("sao"),item("sao-ii"),item("ordinal-scale")));load(1);settle();assertNull(find("catalog-next"));assertNull(find("catalog-previous"));assertEquals(2,FakeActivity.calls.size());}
    @Test public void confirmedNextIsCachedAndPreviousPreservesSearchAndFilters()throws Exception{
        set("query","Sword Art Online");@SuppressWarnings("unchecked") Map<String,String> filters=(Map<String,String>)field("filters");filters.put("type[]","0");FakeActivity.pages.put(1,List.of(item("sao")));FakeActivity.pages.put(2,List.of(item("sao-ii")));load(1);settle();View next=find("catalog-next");assertNotNull(next);next.performClick();settle();assertEquals(2,field("page"));assertNotNull(find("catalog-previous"));assertNull(find("catalog-next"));assertEquals(1,FakeActivity.calls.stream().filter(v->v.startsWith("2:")).count());find("catalog-previous").performClick();settle();assertEquals(1,field("page"));assertNotNull(find("catalog-next"));assertTrue(FakeActivity.calls.stream().allMatch(v->v.contains("Sword Art Online")&&v.contains("type[]=0")));
    }
    @Test public void emptyPageKeepsPreviousAccessibleAndBackReturnsToResults()throws Exception{FakeActivity.pages.put(1,List.of(item("sao")));load(1);settle();load(2);settle();View previous=find("catalog-previous");assertNotNull(previous);assertTrue(previous.isFocusable());assertTrue("Empty page must put focus on Previous",previous.hasFocus());assertNull(find("catalog-next"));activity.onBackPressed();settle();assertEquals(1,field("page"));assertNotNull(find(item("sao").url()));}
    @Test public void failedPageKeepsWorkingPreviousButton()throws Exception{FakeActivity.pages.put(1,List.of(item("sao")));FakeActivity.failing.add(2);load(1);settle();assertNull(find("catalog-next"));load(2);settle();assertNotNull(find("catalog-previous"));find("catalog-previous").performClick();settle();assertEquals(1,field("page"));assertNotNull(find(item("sao").url()));}
    @Test public void repeatedOrRedirectedSamePageIsNotAnotherPage()throws Exception{List<Anime> items=List.of(item("sao"));assertFalse(CatalogPagination.hasMore(items,items));assertFalse(CatalogPagination.hasMore(items,List.of()));assertTrue(CatalogPagination.hasMore(items,List.of(item("sao-ii"))));FakeActivity.pages.put(1,items);FakeActivity.pages.put(2,items);load(1);settle();assertNull(find("catalog-next"));}
    @Test public void slowLookAheadDoesNotDelayCurrentCardsOrAllowPrematureNext()throws Exception{FakeActivity.pages.put(1,List.of(item("sao")));FakeActivity.pages.put(2,List.of(item("sao-ii")));FakeActivity.nextStarted=new CountDownLatch(1);FakeActivity.nextRelease=new CountDownLatch(1);load(1);assertTrue(FakeActivity.nextStarted.await(2,TimeUnit.SECONDS));Shadows.shadowOf(Looper.getMainLooper()).idle();assertNotNull(find(item("sao").url()));assertNull(find("catalog-next"));FakeActivity.nextRelease.countDown();settle();assertNotNull(find("catalog-next"));}
}
